const fs = require('fs/promises');
const path = require('path');
const crypto = require('crypto');
const { removeVariants } = require('./imageVariants');

const PUBLIC_PREFIX = '/uploads';

// Stores files under uploadDir and serves them from <publicUrl>/uploads/<key>.
function createLocalStorage({ uploadDir, publicUrl }) {
  const urlBase = `${publicUrl}${PUBLIC_PREFIX}/`;

  const resolveKey = (key) => {
    const target = path.resolve(uploadDir, key);
    // Keys are generated by save(), but never touch anything outside uploadDir.
    if (!target.startsWith(path.resolve(uploadDir) + path.sep)) throw new Error('Invalid storage key');
    return target;
  };

  return {
    publicPrefix: PUBLIC_PREFIX,
    uploadDir,

    async save(buffer, { folder, extension }) {
      const key = `${folder}/${crypto.randomUUID()}.${extension}`;
      const target = resolveKey(key);
      await fs.mkdir(path.dirname(target), { recursive: true });
      await fs.writeFile(target, buffer);
      return { key, url: urlBase + key };
    },

    async read(key) {
      return fs.readFile(resolveKey(key));
    },

    async remove(key) {
      await fs.rm(resolveKey(key), { force: true });
      await removeVariants(uploadDir, key);
    },

    // Returns the storage key for a URL this adapter produced, or null for anything else.
    keyFromUrl(url) {
      if (typeof url !== 'string' || !url.startsWith(urlBase)) return null;
      const key = url.slice(urlBase.length);
      return /^[a-z]+\/[0-9a-f-]{36}\.[a-z]+$/.test(key) ? key : null;
    }
  };
}

module.exports = createLocalStorage;
